body {
  font-family: sans-serif;
  margin: 0;
  padding: 8px;
  background-color: transparent;
}

.container {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.row-item {
  display: flex;
  align-items: center;
  gap: 12px;
}

.checkbox-label {
  display: flex;
  align-items: center;
  gap: 6px;
  cursor: pointer;
  user-select: none;
}

.text-input {
  padding: 4px 8px;
  border: 1px solid #ccc;
  border-radius: 4px;
  font-size: 14px;
  outline: none;
}

.text-input:focus {
  border-color: #f95959; /* Anpassbar an dein Appsmith-Thema */
}

srcDoc.js:
// Lausche auf Daten, die von Appsmith kommen
window.appsmith.onReady(() => {
  window.appsmith.onModelChange(model => {
    render(model.list);
  });
});
function render(items) {
  const container = document.getElementById("app");
  container.innerHTML = ""; // Container leeren

  if (!items || !Array.isArray(items)) return;
  items.forEach((item, index) => {
    const wrapper = document.createElement("div");
    wrapper.className = "row-item";

    // 1. Checkbox & Label
    const label = document.createElement("label");
    label.className = "checkbox-label";
    const checkbox = document.createElement("input");
    checkbox.type = "checkbox";
    checkbox.checked = !!item.checked;
    checkbox.onchange = e => {
      item.checked = e.target.checked;
      updateAppsmith(items);
    };
    const textSpan = document.createElement("span");
    textSpan.innerText = item.label;
    label.appendChild(checkbox);
    label.appendChild(textSpan);
    wrapper.appendChild(label);

    // 2. Input-Feld (wird nur angezeigt, wenn Checkbox aktiv ist - optional)
    // Wenn es immer sichtbar sein soll, diesen 'if'-Block oder die Klasse anpassen.
    const input = document.createElement("input");
    input.type = "text";
    input.className = "text-input";
    input.placeholder = "Wert eingeben...";
    input.value = item.value || "";

    // Optional: Ein-/Ausblenden basierend auf dem Checkbox-Status
    input.style.display = item.checked ? "inline-block" : "none";
    input.oninput = e => {
      item.value = e.target.value;
      updateAppsmith(items);
    };
    wrapper.appendChild(input);
    container.appendChild(wrapper);
  });
}

// Daten zurück an Appsmith senden
function updateAppsmith(items) {
  window.appsmith.triggerModelUpdate({
    list: items
  });
}

